def count_sequences(n, last, memo):
    if last in memo:
        return memo[last]
    if last == n:
        return 1
    total = 0
    for i in range(n, last):
        if i <= last // 2:
            total += count_sequences(n, i, memo)
    memo[last] = total
    return total

