def preorder_traversal(inorder, postorder):
    inorder_idx = {c: i for i, c in enumerate(inorder)}
    postorder_idx = {c: i for i, c in enumerate(postorder)}
    n = len(inorder)
    graph = [[] for _ in range(n)]
    for i in range(n):
        for j in range(i+1, n):
            if inorder_idx[postorder[j]] > inorder_idx[postorder[i]]:
                graph[i].append(j)
                graph[j].append(i)
    visit = [False] * n
    preorder = []
    def dfs(i):
        nonlocal preorder
        if visit[i]:
            return
        visit[i] = True
        preorder.append(postorder[i])
        for j in graph[i]:
            dfs(j)
    dfs(0)
    return ''.join(preorder)

